var a=279;var i=[{id:`cooking-279-01`,theoryId:279,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What should guide batch size when serving a variable number of guests?`,ua:`Чим слід керуватися під час вибору розміру партії для змінної кількості гостей?`},explanation:{en:`Batch production must balance demand, equipment throughput, quality and food-safety controls.`,ua:`Партійне приготування балансує попит, продуктивність обладнання, якість та харчову безпеку.`},options:[{id:`a`,text:{en:`Only the number of staff birthdays that day`,ua:`Лише кількістю днів народження персоналу`}},{id:`b`,text:{en:`The largest pot available regardless of demand`,ua:`Найбільшою каструлею незалежно від попиту`}},{id:`c`,text:{en:`Demand forecast, equipment capacity and safe holding`,ua:`Прогнозом попиту, місткістю обладнання та безпечним зберіганням`}}],answer:{optionIds:[`c`]}},{id:`cooking-279-02`,theoryId:279,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`A production forecast is guaranteed to equal actual orders exactly.`,ua:`Прогноз виробництва гарантовано точно відповідає фактичним замовленням.`},explanation:{en:`Forecasts are estimates; review sales trends and use contingency plans.`,ua:`Прогнози є оцінками; аналізуйте продажі та плануйте відхилення.`},answer:{value:!1}},{id:`cooking-279-03`,theoryId:279,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match planning terms with their uses.`,ua:`Поєднайте терміни планування з їхнім використанням.`},explanation:{en:`A realistic plan connects demand to available time and capacity.`,ua:`Реалістичний план пов’язує попит із часом і можливостями.`},leftItems:[{id:`l1`,text:{en:`Sales forecast`,ua:`Прогноз продажів`}},{id:`l2`,text:{en:`Station capacity`,ua:`Пропускна здатність станції`}},{id:`l3`,text:{en:`Production sheet`,ua:`Виробничий лист`}}],rightItems:[{id:`r2`,text:{en:`Limits simultaneous production`,ua:`Обмежує одночасне виробництво`}},{id:`r3`,text:{en:`Records planned quantities and preparation times`,ua:`Фіксує планові кількості й час підготовки`}},{id:`r1`,text:{en:`Estimates expected portions`,ua:`Оцінює очікувані порції`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-279-04`,theoryId:279,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A soup station can safely produce 20 portions per batch, with 65 expected orders. What is a sensible plan?`,ua:`Супова станція може безпечно приготувати 20 порцій за партію, очікують 65 замовлень. Який план розумний?`},explanation:{en:`Capacity implies at least four batches (20 + 20 + 20 + 5) unless a different validated method is used.`,ua:`Місткість передбачає щонайменше чотири партії (20 + 20 + 20 + 5), якщо не застосовано інший перевірений метод.`},options:[{id:`a`,text:{en:`Prepare 65 portions and leave them unrefrigerated overnight`,ua:`Приготувати 65 порцій і залишити без охолодження на ніч`}},{id:`b`,text:{en:`Plan four controlled batches and adjust timing to demand`,ua:`Запланувати чотири контрольовані партії та узгодити час із попитом`}},{id:`c`,text:{en:`Overfill the kettle to make 65 portions at once`,ua:`Переповнити котел і зробити 65 порцій одразу`}}],answer:{optionIds:[`b`]}},{id:`cooking-279-05`,theoryId:279,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which data help build a usable production plan?`,ua:`Які дані допомагають створити дієвий виробничий план?`},explanation:{en:`Forecasts, yields and operational limits shape batch plans; storage safety is separate.`,ua:`Прогнози, вихід і виробничі обмеження визначають партії; безпеку зберігання оцінюють окремо.`},options:[{id:`a`,text:{en:`Assumption that leftovers are always safe to serve tomorrow`,ua:`Припущення, що залишки завжди безпечно подавати завтра`}},{id:`b`,text:{en:`Standard recipe yields`,ua:`Стандартний вихід рецептів`}},{id:`c`,text:{en:`Historical orders and reservations`,ua:`Історія замовлень та бронювання`}},{id:`d`,text:{en:`Equipment and staff capacity`,ua:`Можливості обладнання та персоналу`}}],answer:{optionIds:[`c`,`b`,`d`]}},{id:`cooking-279-06`,theoryId:279,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A kitchen needs 83 portions and a validated kettle batch yields 24 portions. What is the minimum whole number of batches?`,ua:`Кухні потрібно 83 порції, а перевірена партія в котлі дає 24 порції. Яка мінімальна ціла кількість партій?`},explanation:{en:`Three batches provide only 72 portions; four can provide up to 96.`,ua:`Три партії дають лише 72 порції; чотири — до 96.`},numericInput:{unit:`units`,unitLabel:{en:`units`,ua:`одиниць`},allowDecimals:!1},answer:{value:4,tolerance:0,unit:`units`}}];var n={theoryId:279,exercises:i};export{n as default,i as exercises,a as theoryId};